<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kto dzwoni?</title><style>body{margin:0;background:#111;color:#fff;font-family:Arial}.navbar{height:70px;background:#1b1b1b;display:flex;align-items:center;padding:0 30px;gap:10px}.logo{font-size:24px;font-weight:bold;margin-right:30px}.navbar a{color:#ccc;text-decoration:none;padding:12px 20px;border-radius:8px}.navbar a.active,.navbar a:hover{background:#333;color:#fff}#app{min-height:calc(100vh - 70px);display:flex;align-items:center;justify-content:center;padding:30px}.panel{width:100%;max-width:900px;background:#202020;border-radius:20px;padding:40px;box-shadow:0 10px 40px #000}.status{text-align:center;font-size:28px;font-weight:bold}.ringing{color:#00e676}.idle{color:#888}.bell{text-align:center;font-size:90px;animation:r .8s infinite}@keyframes r{25%{transform:rotate(15deg)}50%{transform:rotate(-15deg)}75%{transform:rotate(8deg)}}.display-name{text-align:center;font-size:46px;font-weight:bold;margin:15px}.number{text-align:center;font-size:34px;font-weight:bold}.callerid{text-align:center;color:#aaa;font-size:20px;margin:10px}.flag{display:table;margin:20px auto;padding:9px 18px;border-radius:20px;font-weight:bold}.positive{background:#123b25;color:#00e676}.negative{background:#451919;color:#ff5252}.neutral{background:#453b16;color:#ffd740}.note{margin:20px auto;padding:20px;background:#151515;border-left:4px solid #1769aa;max-width:750px}.stats{display:grid;grid-template-columns:repeat(4,1fr);background:#333;gap:1px;margin-top:25px}.stat{background:#151515;padding:20px;text-align:center}.stat strong{display:block;font-size:36px}.no-data{text-align:center;color:#888;padding:50px}.time{text-align:center;margin-top:25px;color:#aaa}@media(max-width:700px){.panel{padding:25px}.display-name{font-size:32px}.number{font-size:26px}.stats{grid-template-columns:repeat(2,1fr)}}</style></head><body><nav class="navbar"><div class="logo">☎ KTO DZWONI?</div><a class="active" href="index.php">Monitor</a><a href="szukaj.php">Szukaj</a></nav><div id="app"><div class="panel"><div id="content"><div class="status idle">BRAK AKTYWNEGO POŁĄCZENIA</div><div class="no-data">Oczekiwanie na połączenie...</div></div></div></div><script>let uid=null,start=null;const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const n=v=>{v=String(v||'');return v.length===9?'+48 '+v.slice(0,3)+' '+v.slice(3,6)+' '+v.slice(6):v};function t(){if(!start)return;let s=Math.floor((Date.now()-start)/1000),m=String(Math.floor(s/60)).padStart(2,'0'),x=String(s%60).padStart(2,'0'),z=document.getElementById('timer');if(z)z.textContent=m+':'+x}function show(d){if(uid!==d.uniqueid){uid=d.uniqueid;start=new Date(d.started_at.replace(' ','T'))}let h='<div class="bell">🔔</div><div class="status ringing">POŁĄCZENIE PRZYCHODZĄCE</div>';if(d.display_name)h+='<div class="display-name">'+e(d.display_name)+'</div>';h+='<div class="number">'+e(n(d.number))+'</div>';if(d.callerid)h+='<div class="callerid">'+e(d.callerid)+'</div>';if(d.sentiment)h+='<div class="flag '+e(d.sentiment)+'">'+(d.sentiment==='positive'?'🟢 POZYTYWNY':d.sentiment==='negative'?'🔴 NEGATYWNY':'🟡 NEUTRALNY')+'</div>';if(d.note)h+='<div class="note"><b>WŁASNA INFORMACJA</b><br>'+e(d.note)+'</div>';if(+d.has_data===1)h+='<div class="stats"><div class="stat"><strong>'+e(d.positive)+'</strong>pozytywnych</div><div class="stat"><strong>'+e(d.negative)+'</strong>negatywnych</div><div class="stat"><strong>'+e(d.neutral)+'</strong>neutralnych</div><div class="stat"><strong>'+e(d.total)+'</strong>opinii</div></div>';h+='<div class="time">Czas połączenia: <strong id="timer">00:00</strong></div>';document.getElementById('content').innerHTML=h;t()}function idle(){uid=null;start=null;document.getElementById('content').innerHTML='<div class="status idle">BRAK AKTYWNEGO POŁĄCZENIA</div><div class="no-data">Oczekiwanie na połączenie...</div>'}async function check(){try{let r=await fetch('api.php?t='+Date.now(),{cache:'no-store'}),d=await r.json();d.active?show(d):idle()}catch(x){console.error(x)}}setInterval(check,1000);setInterval(t,1000);check();</script></body></html>